import{_ as a,o as e,c as s,a2 as i}from"./chunks/framework.CBWbbCW8.js";const u=JSON.parse('{"title":"快速开始","description":"","frontmatter":{},"headers":[],"relativePath":"guide/quick-start.md","filePath":"guide/quick-start.md","lastUpdated":1784967005000}'),d={name:"guide/quick-start.md"};function n(o,t,l,h,r,p){return e(),s("div",null,[...t[0]||(t[0]=[i(`<h1 id="快速开始" tabindex="-1">快速开始 <a class="header-anchor" href="#快速开始" aria-label="Permalink to &quot;快速开始&quot;">​</a></h1><p>这一页带你从零完成一次 API 调用。你只需要准备一个 DouDi.ai 账号和一个可以发送 HTTP 请求的工具，例如终端、Postman、Apifox、Cherry Studio、Lobe Chat 或任意 OpenAI 兼容客户端。</p><h2 id="_1-注册或登录" tabindex="-1">1. 注册或登录 <a class="header-anchor" href="#_1-注册或登录" aria-label="Permalink to &quot;1. 注册或登录&quot;">​</a></h2><p>打开 <a href="https://doudi.ai" target="_blank" rel="noreferrer">https://doudi.ai</a>，点击登录或注册。公开状态接口显示当前站点启用了密码登录和密码注册，并启用了 Turnstile 校验，所以注册时可能需要完成人机验证。</p><h2 id="_2-进入控制台" tabindex="-1">2. 进入控制台 <a class="header-anchor" href="#_2-进入控制台" aria-label="Permalink to &quot;2. 进入控制台&quot;">​</a></h2><p>登录后进入控制台。常用模块包括：</p><table tabindex="0"><thead><tr><th>模块</th><th>用途</th></tr></thead><tbody><tr><td>API Keys</td><td>创建、复制、启用、禁用或删除 API Key。</td></tr><tr><td>Playground</td><td>在线测试模型请求。</td></tr><tr><td>Models</td><td>查看登录后可用模型。</td></tr><tr><td>Wallet</td><td>查看余额、额度和充值记录。</td></tr><tr><td>Usage Logs</td><td>查看调用日志和扣费记录。</td></tr></tbody></table><h2 id="_3-创建-api-key" tabindex="-1">3. 创建 API Key <a class="header-anchor" href="#_3-创建-api-key" aria-label="Permalink to &quot;3. 创建 API Key&quot;">​</a></h2><p>进入 <code>API Keys</code> 页面，创建一个新 Key。创建后请立即复制并妥善保存，因为很多平台只会在创建时完整展示一次密钥。</p><p>详细步骤见：<a href="/diudi-docs/guide/create-api-key">创建 API Key</a>。</p><h2 id="_4-配置客户端" tabindex="-1">4. 配置客户端 <a class="header-anchor" href="#_4-配置客户端" aria-label="Permalink to &quot;4. 配置客户端&quot;">​</a></h2><p>OpenAI 兼容客户端一般需要两个值：</p><table tabindex="0"><thead><tr><th>配置项</th><th>推荐填写</th></tr></thead><tbody><tr><td>Base URL</td><td><code>https://doudi.ai/v1</code></td></tr><tr><td>API Key</td><td>你在控制台创建的 Key</td></tr></tbody></table><p>如果客户端要求填写完整接口地址，可以使用：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>https://doudi.ai/v1/chat/completions</span></span></code></pre></div><h2 id="_5-发送一次请求" tabindex="-1">5. 发送一次请求 <a class="header-anchor" href="#_5-发送一次请求" aria-label="Permalink to &quot;5. 发送一次请求&quot;">​</a></h2><p>将 <code>YOUR_API_KEY</code> 替换成你自己的 API Key，将 <code>model</code> 替换成你账号可用的模型。</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://doudi.ai/v1/chat/completions</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -H</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;Authorization: Bearer YOUR_API_KEY&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -H</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;Content-Type: application/json&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -d</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;{</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">    &quot;model&quot;: &quot;gpt-5.6&quot;,</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">    &quot;messages&quot;: [</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">      { &quot;role&quot;: &quot;user&quot;, &quot;content&quot;: &quot;用一句话介绍 DouDi.ai&quot; }</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">    ]</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  }&#39;</span></span></code></pre></div><h2 id="_6-查看调用结果" tabindex="-1">6. 查看调用结果 <a class="header-anchor" href="#_6-查看调用结果" aria-label="Permalink to &quot;6. 查看调用结果&quot;">​</a></h2><p>请求成功后，你可以回到控制台查看：</p><ul><li><code>Usage Logs</code>：确认请求时间、模型、消耗额度和状态。</li><li><code>Wallet</code>：确认余额或额度变化。</li><li><code>Models</code>：确认当前账号能使用哪些模型和分组。</li></ul><h2 id="常见错误" tabindex="-1">常见错误 <a class="header-anchor" href="#常见错误" aria-label="Permalink to &quot;常见错误&quot;">​</a></h2><table tabindex="0"><thead><tr><th>现象</th><th>排查方向</th></tr></thead><tbody><tr><td><code>401 Unauthorized</code></td><td>API Key 未填写、填写错误，或 Key 已被禁用。</td></tr><tr><td>模型不可用</td><td>账号分组没有该模型权限，或模型名称填写错误。</td></tr><tr><td>余额不足</td><td>到 <code>Wallet</code> 查看余额和额度。</td></tr><tr><td>客户端连接失败</td><td>检查 Base URL 是否为 <code>https://doudi.ai/v1</code>，不要多写或少写 <code>/v1</code>。</td></tr></tbody></table>`,23)])])}const k=a(d,[["render",n]]);export{u as __pageData,k as default};
